import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import 'package:image_picker/image_picker.dart';
import '../models/models.dart';
import '../services/ai_food_service.dart';
import '../services/storage_service.dart';
import '../widgets/app_card.dart';

class FoodScreen extends StatefulWidget{const FoodScreen({super.key});@override State<FoodScreen> createState()=>_FoodScreenState();}
class _FoodScreenState extends State<FoodScreen>{
 final ai=AiFoodService();final picker=ImagePicker();List<Meal> meals=[];Map<String,double>? goals;bool loading=true;String get today=>DateFormat('yyyy-MM-dd').format(DateTime.now());
 @override void initState(){super.initState();_load();}
 Future<void> _load()async{final raw=await StorageService.read('meals');final g=await StorageService.read('nutrition_goals');meals=raw.map(Meal.fromJson).toList();if(g.isNotEmpty){goals=g.first.map((k,v)=>(MapEntry(k.toString(),(v as num).toDouble())));}setState(()=>loading=false);if(goals==null&&mounted)WidgetsBinding.instance.addPostFrameCallback((_)=>_setup());}
 Future<void> _setup()async{final age=TextEditingController(),weight=TextEditingController(),height=TextEditingController();String sex='Masculino',activity='Moderado',objective='Manter peso';final ok=await showDialog<bool>(context:context,barrierDismissible:false,builder:(c)=>StatefulBuilder(builder:(c,ss)=>AlertDialog(title:const Text('Vamos configurar sua alimentação'),content:SingleChildScrollView(child:Column(children:[const Text('Responda algumas perguntas para estimarmos suas metas diárias.'),TextField(controller:age,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Idade')),TextField(controller:weight,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Peso (kg)')),TextField(controller:height,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Altura (cm)')),DropdownButtonFormField<String>(initialValue:sex,items:['Masculino','Feminino'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)ss(()=>sex=v);},decoration:const InputDecoration(labelText:'Sexo')),DropdownButtonFormField<String>(initialValue:activity,items:['Sedentário','Levemente ativo','Moderado','Muito ativo','Extremamente ativo'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)ss(()=>activity=v);},decoration:const InputDecoration(labelText:'Nível de atividade')),DropdownButtonFormField<String>(initialValue:objective,items:['Perder peso','Manter peso','Ganhar peso'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)ss(()=>objective=v);},decoration:const InputDecoration(labelText:'Objetivo')),const SizedBox(height:10),const Text('As metas são estimativas e não substituem orientação de nutricionista ou médico.',style:TextStyle(fontSize:12))])),actions:[FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Calcular'))])));if(ok!=true)return;final a=double.tryParse(age.text.replaceAll(',','.')),w=double.tryParse(weight.text.replaceAll(',','.')),h=double.tryParse(height.text.replaceAll(',','.'));if(a==null||w==null||h==null||a<=0||w<=0||h<=0){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Preencha os dados corretamente.')));return;}
 const factors={'Sedentário':1.2,'Levemente ativo':1.375,'Moderado':1.55,'Muito ativo':1.725,'Extremamente ativo':1.9};double bmr=sex=='Masculino'?10*w+6.25*h-5*a+5:10*w+6.25*h-5*a-161;double kcal=bmr*factors[activity]!+(objective=='Perder peso'?-400:objective=='Ganhar peso'?300:0);double protein=w*2;double fat=kcal*.27/9;double carbs=(kcal-protein*4-fat*9)/4;goals={'calories':kcal,'protein':protein,'carbs':carbs,'fat':fat};await StorageService.write('nutrition_goals',[goals!]);setState((){});}
 Future<void> _manual()async{final n=TextEditingController(),k=TextEditingController(),p=TextEditingController(),c=TextEditingController(),f=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(x)=>AlertDialog(title:const Text('Adicionar refeição'),content:SingleChildScrollView(child:Column(children:[TextField(controller:n,decoration:const InputDecoration(labelText:'Alimento / refeição')),TextField(controller:k,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Calorias (kcal)')),TextField(controller:p,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Proteína (g)')),TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Carboidratos (g)')),TextField(controller:f,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Gorduras (g)'))])),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('Adicionar'))]));if(ok==true&&n.text.trim().isNotEmpty){meals.add(Meal(id:DateTime.now().microsecondsSinceEpoch.toString(),date:today,type:'Refeição',food:n.text.trim(),calories:double.tryParse(k.text.replaceAll(',','.'))??0,protein:double.tryParse(p.text.replaceAll(',','.'))??0,carbs:double.tryParse(c.text.replaceAll(',','.'))??0,fat:double.tryParse(f.text.replaceAll(',','.'))??0));await _save();setState((){});}}
 Future<void> _save()=>StorageService.write('meals',meals.map((e)=>e.toJson()).toList());
 Future<void> _aiText()async{final t=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('IA por texto'),content:TextField(controller:t,maxLines:4,decoration:const InputDecoration(hintText:'Ex.: 200g arroz, 150g frango e feijão')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Analisar'))]));if(ok!=true||t.text.trim().isEmpty)return;try{final r=await ai.estimateText(t.text);if(mounted)_showResult(r);}catch(e){if(mounted)_err(e.toString());}}
 Future<void> _camera()async{final p=await picker.pickImage(source:ImageSource.camera,imageQuality:80);if(p==null)return;try{final r=await ai.estimateImage(p.path);if(mounted)_showResult(r);}catch(e){if(mounted)_err(e.toString());}}
 void _err(String x)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(x)));
 Future<void> _showResult(FoodResult r)async{final add=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Estimativa nutricional'),content:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[...r.items.map((i)=>ListTile(contentPadding:EdgeInsets.zero,title:Text(i.name),subtitle:Text('${i.grams.toStringAsFixed(0)}g • ${i.calories.toStringAsFixed(0)} kcal • P ${i.protein.toStringAsFixed(1)}g • C ${i.carbs.toStringAsFixed(1)}g • G ${i.fat.toStringAsFixed(1)}g'))),const Divider(),Text('${r.calories.toStringAsFixed(0)} kcal • P ${r.protein.toStringAsFixed(1)}g • C ${r.carbs.toStringAsFixed(1)}g • G ${r.fat.toStringAsFixed(1)}g'),const SizedBox(height:8),Text(r.note,style:Theme.of(c).textTheme.bodySmall)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('NÃO CONTAR')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('CONTAR'))]));if(add==true){meals.add(Meal(id:DateTime.now().microsecondsSinceEpoch.toString(),date:today,type:'Refeição',food:r.items.map((i)=>i.name).join(', '),calories:r.calories,protein:r.protein,carbs:r.carbs,fat:r.fat,source:'ai'));await _save();setState((){});}}
 @override Widget build(BuildContext context){if(loading)return const Center(child:CircularProgressIndicator());final tm=meals.where((m)=>m.date==today);final kcal=tm.fold(0.0,(s,m)=>s+m.calories),p=tm.fold(0.0,(s,m)=>s+m.protein),carb=tm.fold(0.0,(s,m)=>s+m.carbs),fat=tm.fold(0.0,(s,m)=>s+m.fat);return SafeArea(child:ListView(padding:const EdgeInsets.all(16),children:[Row(children:[Expanded(child:Text('Alimentação',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))),PopupMenuButton<String>(onSelected:(v){if(v=='text')_aiText();if(v=='camera')_camera();if(v=='goals')_setup();},itemBuilder:(_)=>const[PopupMenuItem(value:'text',child:Text('🤖 Analisar por texto')),PopupMenuItem(value:'camera',child:Text('📷 Analisar com câmera')),PopupMenuItem(value:'goals',child:Text('⚙️ Recalcular metas'))])]),if(goals!=null)AppCard(child:Column(children:[_bar(context,'Calorias',kcal,goals!['calories']!, 'kcal'),_bar(context,'Proteína',p,goals!['protein']!,'g'),_bar(context,'Carboidratos',carb,goals!['carbs']!,'g'),_bar(context,'Gorduras',fat,goals!['fat']!,'g')])),const SizedBox(height:8),FilledButton.icon(onPressed:_manual,icon:const Icon(Icons.add),label:const Text('Adicionar refeição manualmente')),...tm.map((m)=>AppCard(child:ListTile(contentPadding:EdgeInsets.zero,title:Text(m.food),subtitle:Text('${m.calories.toStringAsFixed(0)} kcal • P ${m.protein.toStringAsFixed(1)}g • C ${m.carbs.toStringAsFixed(1)}g • G ${m.fat.toStringAsFixed(1)}g'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{meals.remove(m);await _save();setState((){});}))) ]));}
 Widget _bar(BuildContext c,String name,double value,double goal,String unit){final pct=goal<=0?0:(value/goal).clamp(0.0,1.0);return Padding(padding:const EdgeInsets.symmetric(vertical:5),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text(name)),Text('${value.toStringAsFixed(0)} / ${goal.toStringAsFixed(0)} $unit')]),LinearProgressIndicator(value:pct)]));}
}
